item.content:encoded:
/* PROFILE CARD CONTAINER */
/* Profile Header Background */
.um-header, .um-profile-photo, .um-cover, .um-profile-meta {
    background: #181818 !important;
    border: none !important;
}

/* Card/Section Backgrounds */
.um-profile-body, .um-profile-content, .um {
    background: #181818 !important;
    border: 1px solid #242424 !important;
    border-radius: 14px !important;
    box-shadow: none !important;
}

/* Tab Row Background */
.um-profile-nav {
    background: #222 !important;
    border-bottom: 2px solid #191919 !important;
}

/* Tabs Buttons */
.um-profile-nav .um-profile-nav-item a {
    background: #0256ff !important;
    color: #fff !important;
    border-radius: 2px !important;
    font-weight: 500;
    margin: 0 2px;
}
.um-profile-nav .um-profile-nav-item a.active,
.um-profile-nav .um-profile-nav-item a:hover {
    background: #003eb8 !important;
    color: #fff !important;
}

/* Labels & Headings */
.um-field-label,
.um-profile-heading {
    color: #fff !important;
    font-weight: 600;
    font-size: 15px;
}

/* Field Values */
.um-field-value {
    color: #eaeaea !important;
    background: #222 !important;
    border-radius: 7px;
    border: 1px solid #282828;
    padding: 11px 18px;
    margin-bottom: 16px;
    display: block;
}

/* Remove white lines and borders */
.um-profile-photo, .um-cover {
    border: none !important;
    box-shadow: none !important;
}
.um-profile-meta {
    border-bottom: none !important;
}

/* Website/email links in profile */
.um-field-value a {
    color: #00aaff !important;
    text-decoration: underline;
}

/* Remove white around profile card/container */
.um-container,
.um {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
}

/* Responsive adjustments */
@media (max-width: 600px) {
    .um-profile-body {
        padding: 12px 4px 8px 4px !important;
    }
    .um-field-label {
        font-size: 14px !important;
    }
}

/* Adds left padding to the profile name under the avatar */
.um-profile-meta .um-name {
    padding-left: 24px !important; /* Adjust px value as needed */
    font-weight: 700;              /* Optional: make the name bolder */
    color: #d2d2d2 !important;     /* Optional: adjust color for contrast */
}

/* For better alignment, add padding to the status dot if needed */
.um-profile-meta .um-online-status {
    margin-left: 8px;
}

/* Add spacing below profile tab navigation */
.um-profile-nav {
    margin-bottom: 26px !important;   /* Adjust px as needed */
    padding-bottom: 10px !important;  /* Optional, extra space inside */
}

/* Or if you only want space below, this is enough: */
.um-profile-nav {
    margin-bottom: 26px !important;
}

/* Main timeline (wall) container */
.um-activity, .um-activity-list, .um-activity-widget, .um-activity-body,
.um-activity-list-item, .um-activity-post, .um-activity-comments, .um-activity-comment,
.um-activity-comment-box, .um-activity-comment-list, .um-activity-comment-form,
.um-activity-post-form, .um-activity-post-box, .um-activity-post-form textarea,
.um-activity-post-form input[type="text"], .um-activity-post-form input[type="submit"],
.um-activity-comment-form textarea, .um-activity-comment-form input[type="text"],
.um-activity-comment-form input[type="submit"] {
    background: #181818 !important;   /* Match your site’s black */
    color: #f0f0f0 !important;
    border: 1px solid #232323 !important;
    box-shadow: none !important;
}

/* Activity input area */
.um-activity-post-form textarea,
.um-activity-post-form input[type="text"] {
    background: #191919 !important;
    color: #f5f5f5 !important;
}

/* Activity cards/comments */
.um-activity-list-item,
.um-activity-post,
.um-activity-comments,
.um-activity-comment,
.um-activity-comment-box,
.um-activity-post-box {
    background: #181818 !important;
    color: #eaeaea !important;
    border: 1px solid #232323 !important;
    border-radius: 10px !important;
}

/* Comment and post buttons */
.um-activity-btn, .um-activity-btn-primary, .um-activity-post-btn, .um-activity-comment-btn,
.um-activity-comment-form input[type="submit"] {
    background: #0256ff !important;
    color: #fff !important;
    border-radius: 4px !important;
    border: none !important;
    font-weight: 600;
    transition: background 0.2s;
}
.um-activity-btn:hover, .um-activity-btn-primary:hover,
.um-activity-post-btn:hover, .um-activity-comment-btn:hover {
    background: #003eb8 !important;
}

/* Username and time */
.um-activity-author, .um-activity-list-item .um-activity-time {
    color: #57a3ff !important;
}

/* Like, comment, icons */
.um-activity-action {
    color: #bbbbbb !important;
}
.um-activity-action:hover {
    color: #ffffff !important;
}

/* Remove double borders, spacing */
.um-activity-list, .um-activity, .um-activity-comments, .um-activity-post-form {
    box-shadow: none !important;
    border: none !important;
}

/* Placeholder text for inputs/comments */
.um-activity-post-form textarea::placeholder,
.um-activity-comment-form textarea::placeholder,
.um-activity-post-form input::placeholder,
.um-activity-comment-form input::placeholder {
    color: #bbbbbb !important;
    opacity: 1;
}

/* Remove any leftover white for nested elements */
.um-activity-list *, .um-activity-post *, .um-activity-comments *, .um-activity-comment * {
    background: transparent !important;
}

/* Force all background in activity/timeline to dark */
.um-activity-post-form,
.um-activity-list-item,
.um-activity-comment,
.um-activity-comments,
.um-activity-comment-box,
.um-activity-comment-list,
.um-activity-post,
.um-activity-post-box,
.um-activity-comment-form,
.um-activity-post-form,
.um-activity-post-form .um-activity-post-content,
.um-activity-list-item .um-activity-content,
.um-activity-list-item .um-activity-author,
.um-activity-list-item .um-activity-time,
.um-activity-actions,
.um-activity-comment-form,
.um-activity-comment-form textarea,
.um-activity-comment-form input,
.um-activity-comment-form input[type="text"],
.um-activity-comment-form input[type="submit"],
.um-activity-post-form textarea,
.um-activity-post-form input[type="text"] {
    background: #191919 !important;
    color: #f2f2f2 !important;
    border: 1px solid #282828 !important;
}

/* Remove white on all child divs and spans for extra insurance */
.um-activity-post-form *,
.um-activity-list-item *,
.um-activity-comment *,
.um-activity-comments *,
.um-activity-comment-box *,
.um-activity-comment-list *,
.um-activity-post *,
.um-activity-post-box *,
.um-activity-comment-form * {
    background: transparent !important;
    color: #e0e0e0 !important;
    box-shadow: none !important;
}

/* Comment box and textarea: better padding */
.um-activity-comment-form textarea,
.um-activity-post-form textarea {
    padding: 12px 16px !important;
    min-height: 48px !important;
    border-radius: 6px !important;
    font-size: 16px !important;
}

/* Comment action buttons */
.um-activity-comment-btn,
.um-activity-post-btn,
.um-activity-btn {
    background: #0256ff !important;
    color: #fff !important;
    border: none !important;
    border-radius: 4px !important;
    padding: 7px 18px !important;
    font-weight: 600;
    transition: background 0.2s;
}
.um-activity-comment-btn:hover,
.um-activity-post-btn:hover,
.um-activity-btn:hover {
    background: #003eb8 !important;
}

/* Post on your wall label */
.um-activity-post-form label,
.um-activity-list-item .um-activity-author {
    color: #fafafa !important;
    font-weight: 600;
    font-size: 16px;
}

/* Placeholder text in comment and post boxes */
.um-activity-post-form textarea::placeholder,
.um-activity-comment-form textarea::placeholder,
.um-activity-post-form input::placeholder,
.um-activity-comment-form input::placeholder {
    color: #888 !important;
    opacity: 1;
}

/* Fix any white for "Like", "Comment" bar */
.um-activity-actions {
    background: #191919 !important;
}

/* Fix for post/comment submit buttons */
.um-activity-post-form input[type="submit"],
.um-activity-comment-form input[type="submit"] {
    background: #0256ff !important;
    color: #fff !important;
    border-radius: 4px !important;
    border: none !important;
    font-weight: 600;
    padding: 7px 18px !important;
}*/

