.event_listings_main .wpem-event-layout-wrapper {
    background: rgba(33, 38, 54, 0.99);
    border-radius: 18px;
    box-shadow: 0 6px 36px rgba(0,0,0,0.25);
    border: 1.5px solid #2a2f56;
    margin-bottom: 2rem;
    transition: box-shadow 0.25s, background 0.25s;
    overflow: hidden;
    min-height: 280px;
}

.event_listings_main .wpem-event-layout-wrapper:hover {
    background: linear-gradient(95deg, #28306c 0%, #6949d1 100%);
    box-shadow: 0 16px 48px rgba(34,34,74,0.23);
    border-color: #6c47e7;
}

.event_listings_main .wpem-event-banner-img {
    border-radius: 12px 12px 0 0;
    min-height: 140px;
    background-size: cover !important;
    background-position: center center !important;
    box-shadow: 0 4px 18px rgba(0,0,0,0.16);
}

/* Title */
.event_listings_main .wpem-event-title h3 {
    font-size: 1.45rem !important;
    font-weight: 900 !important;
    letter-spacing: 0.5px;
    color: #fff !important;
    margin-bottom: 0.5rem;
    text-shadow: 0 2px 8px rgba(0,0,0,0.08);
    transition: color 0.2s;
}

/* Date */
.event_listings_main .wpem-event-date {
    font-size: 1rem;
    color: #4cc9f0 !important;
    font-weight: 700;
    letter-spacing: 0.5px;
    margin-bottom: 0.3rem;
}

/* Details */
.event_listings_main .wpem-event-details {
    padding: 1.1rem 1.4rem;
    color: #d4d8eb !important;
    font-size: 1.02rem;
}

/* Location */
.event_listings_main .wpem-event-location-text {
    color: #8cf7fa !important;
    font-weight: 500;
    font-size: 1rem;
    margin-top: 0.5rem;
}

@media (max-width: 900px) {
    .event_listings_main .wpem-event-layout-wrapper {
        min-height: 180px;
        padding: 0.7rem;
    }
    .event_listings_main .wpem-event-details {
        padding: 0.6rem 0.7rem;
    }
}
/* Make all event card text white */
.event_listings_main .wpem-event-layout-wrapper,
.event_listings_main .wpem-event-layout-wrapper * {
    color: #fff !important;
}

.event_listings_main .wpem-event-title h3 {
    color: #fff !important;
}

.event_listings_main .wpem-event-date,
.event_listings_main .wpem-event-date-type,
.event_listings_main .wpem-event-date-type *,
.event_listings_main .wpem-event-date-time-text,
.event_listings_main .wpem-event-location-text,
.event_listings_main .wpem-event-details {
    color: #fff !important;
}

.event_listings_main .wpem-form-label,
.event_listings_main .wpem-form-group,
.event_listings_main .wpem-form-group * {
    color: #fff !important;
}

/* --- Box View: Hover --- */
.wpem-event-box-layout.wpem-active-layout ~ .event_listings_main .wpem-event-layout-wrapper:hover {
    background: linear-gradient(90deg, #3a33d1 0%, #0140fe 100%) !important;
    box-shadow: 0 10px 40px rgba(1,64,254,0.16), 0 1.5px 7px #0140fe40;
    border-color: #0140fe !important;
    color: #fff !important;
}

/* Keep text white in Box View hover */
.wpem-event-box-layout.wpem-active-layout ~ .event_listings_main .wpem-event-layout-wrapper:hover *,
.wpem-event-box-layout.wpem-active-layout ~ .event_listings_main .wpem-event-layout-wrapper * {
    color: #fff !important;
}

/* --- List View: Keep Background Simple --- */
.wpem-event-list-layout.wpem-active-layout ~ .event_listings_main .wpem-event-layout-wrapper,
.wpem-event-list-layout.wpem-active-layout ~ .event_listings_main .wpem-event-layout-wrapper:hover {
    background: #232333 !important;
    border-color: #2a2f56 !important;
    color: #fff !important;
}

.wpem-event-listing-list-view.wpem-event-listings .wpem-event-layout-wrapper .event_listing {
    margin: 0;
    display: inline-flex
;
    width: 100%;
    padding: 23px 17px;
     border-left: none;
    transition: border .2s;
}

.wpem-event-listings.wpem-event-listing-box-view .wpem-event-layout-wrapper .wpem-event-banner .wpem-event-date .wpem-event-date-type .wpem-from-date {
    display: inline-block;
    float: left;
    text-align: center;
    background: #0140fe;
    padding: 10px 15px;
    width: auto;
    height: auto;
    position: absolute;
    top: 15px;
    left: 15px;
    border-radius: 4px;
    box-shadow: 5px 3px 15px rgba(0, 0, 0, .2);
}
.wpem-event-listings-header .wpem-event-listing-header-title .wpem-heading-text {
    font-size: 24px;
    color: #fff;
    line-height: 1.42;
    font-weight: 500;
    margin: 0;
}
.wpem-event-listing-list-view .wpem-event-box-col:last-of-type .wpem-event-layout-wrapper {
    /* border-bottom: 1px solid var(--wpem-gray-border-color); */
