:{s:3:"hex";s:7:"#ebebeb";s:2:"id";s:6:"vbnfvt";s:4:"name";s:9:"Color #11";}}s:4:"text";s:420:"<p>- Hip-Hop Vibes Night at Rack’em Up, Spartanburg, SC, in collaboration with promoter<br />Marcus “Hype” Johnson. - Date: March 30, 2025</p><p>🎧 "Feel the energy at Hip-Hop Vibes Night featuring Dboy Stackalini! 🔥 Happening on March 30, 2025, at Rack’em Up, Spartanburg, SC. Hosted by Marcus “Hype” Johnson, this event is packed with live performances and exclusive meet-and-greet opportunities!"</p>";s:7:"_margin";a:1:{s:3:"top";s:2:"10";}}}i:16;a:5:{s:2:"id";s:6:"eagpmv";s:4:"name";s:6:"button";s:6:"parent";s:6:"hczinw";s:8:"children";a:0:{}s:8:"settings";a:6:{s:4:"text";s:10:"Redeem Now";s:11:"_typography";a:2:{s:11:"font-family";s:7:"Poppins";s:14:"text-transform";s:9:"uppercase";}s:5:"style";s:7:"primary";s:10:"_cssCustom";s:1743:"#brxe-eagpmv,
#brxe-eagpmv::after {
 padding: 16px 20px;
 font-size: 18px;
 background: linear-gradient(45deg, transparent 5%, #0140fe 5%);
 border: 0;
 color: #fff;
 letter-spacing: 3px;
 line-height: 1;
 box-shadow: 6px 0px 0px #00e6f6;
 outline: transparent;
 position: relative;
}

#brxe-eagpmv::after {
 --slice-0: inset(50% 50% 50% 50%);
 --slice-1: inset(80% -6px 0 0);
 --slice-2: inset(50% -6px 30% 0);
 --slice-3: inset(10% -6px 85% 0);
 --slice-4: inset(40% -6px 43% 0);
 --slice-5: inset(80% -6px 5% 0);
 content: "Redeem Now";
 display: block;
 position: absolute;
 top: 0;
 left: 0;
 right: 0;
 bottom: 0;
 background: linear-gradient(45deg, transparent 3%, ##e30b5d 3%, #e30b5d 5%, #ff013c 5%);
 text-shadow: -3px -3px 0px #f8f005, 3px 3px 0px #00e6f6;
 clip-path: var(--slice-0);
}

#brxe-eagpmv:hover::after {
 animation: 1s glitch;
 animation-timing-function: steps(2, end);
}

@keyframes glitch {
 0% {
  clip-path: var(--slice-1);
  transform: translate(-20px, -10px);
 }

 10% {
  clip-path: var(--slice-3);
  transform: translate(10px, 10px);
 }

 20% {
  clip-path: var(--slice-1);
  transform: translate(-10px, 10px);
 }

 30% {
  clip-path: var(--slice-3);
  transform: translate(0px, 5px);
 }

 40% {
  clip-path: var(--slice-2);
  transform: translate(-5px, 0px);
 }

 50% {
  clip-path: var(--slice-3);
  transform: translate(5px, 0px);
 }

 60% {
  clip-path: var(--slice-4);
  transform: translate(5px, 10px);
 }

 70% {
  clip-path: var(--slice-2);
  transform: translate(-10px, 10px);
 }

 80% {
  clip-path: var(--slice-5);
  transform: translate(20px, -10px);
 }

 90% {
  clip-path: var(--slice-1);
  transform: translate(-10px, 0px);
 }

 100% {
  clip-path: var(--slice-1);
  transform: translate(0);
 }
}
